@import url("https://fonts.googleapis.com/css2?family=Inter:wght@500;700;800;900&display=swap");
:root{
  --ah-sidebar:108px;--ah-topbar:78px;--ah-bg:#030712;--ah-text:#f4f8ff;--ah-muted:rgba(227,236,255,.84);--ah-cyan:#75ecff;--ah-blue:#59b7ff;--ah-violet:#a477ff;--ah-pink:#f15fe5;--ah-border:rgba(117,224,255,.22);--ah-shadow:0 24px 80px rgba(0,0,0,.32);
}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;min-height:100vh;background:#030712;color:var(--ah-text);font-family:Inter,system-ui,sans-serif;overflow-x:hidden}a{color:inherit;text-decoration:none}button,input{font:inherit}svg{display:block;width:1em;height:1em;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.ah-body::before{content:"";position:fixed;inset:0;background:#030712 url('assets/space_bg.jpg') center/cover no-repeat;z-index:-3}.ah-body::after{content:"";position:fixed;inset:0;background:none;z-index:-2;pointer-events:none}.ah-stars{position:fixed;inset:0;z-index:-1;background-image:linear-gradient(rgba(117,224,255,.028) 1px,transparent 1px),linear-gradient(90deg,rgba(117,224,255,.028) 1px,transparent 1px);background-size:80px 80px;opacity:.10;pointer-events:none}
.ah-sidebar{position:fixed;left:0;top:0;bottom:0;width:var(--ah-sidebar);z-index:50;background:linear-gradient(180deg,rgba(2,9,22,.94),rgba(3,12,27,.88));border-right:1px solid rgba(117,224,255,.18);display:flex;flex-direction:column;align-items:center;padding:20px 12px;gap:22px;box-shadow:18px 0 60px rgba(0,0,0,.18)}.ah-logo{width:84px;height:84px;display:grid;place-items:center;border-radius:24px;background:rgba(4,18,38,.10)}.ah-logo-mark{width:74px;height:74px;background:url('data:image/png;base64,') center/contain no-repeat;filter:drop-shadow(0 0 14px rgba(117,224,255,.40))}.ah-side-nav{width:100%;display:flex;flex-direction:column;gap:12px;align-items:center}.ah-side-nav a,.ah-side-nav button{width:60px;height:54px;border-radius:18px;display:grid;place-items:center;background:transparent;color:rgba(235,245,255,.86);border:1px solid transparent;cursor:pointer;transition:.18s}.ah-side-nav a svg,.ah-side-nav button svg{width:22px;height:22px}.ah-side-nav a:hover,.ah-side-nav button:hover,.ah-side-nav .is-active{color:#fff;background:rgba(78,171,255,.14);border-color:rgba(117,224,255,.34);box-shadow:0 0 24px rgba(89,183,255,.18), inset 0 0 18px rgba(117,224,255,.05)}
.ah-topbar{position:fixed;left:var(--ah-sidebar);right:0;top:0;height:var(--ah-topbar);z-index:40;display:flex;align-items:center;justify-content:space-between;padding:0 34px 0 58px;background:rgba(3,10,24,.82);backdrop-filter:blur(12px);border-bottom:1px solid rgba(117,224,255,.16)}.ah-top-nav{display:flex;align-items:center;gap:38px;font-weight:850;color:rgba(235,245,255,.86)}.ah-top-nav a{position:relative;padding:28px 0}.ah-top-nav a:hover,.ah-top-nav .is-active{color:var(--ah-cyan)}.ah-top-nav .is-active::after{content:"";position:absolute;left:0;right:0;bottom:0;height:2px;background:linear-gradient(90deg,var(--ah-cyan),var(--ah-violet));box-shadow:0 0 16px var(--ah-cyan)}.ah-topbar-right{display:flex;align-items:center;gap:14px}.ah-lang-switch{display:flex;gap:8px;padding:6px;border-radius:16px;background:rgba(4,16,37,.42);border:1px solid rgba(117,224,255,.22)}.ah-lang-switch button{min-width:42px;height:36px;border-radius:12px;border:1px solid transparent;background:transparent;color:rgba(239,247,255,.86);font-weight:900;cursor:pointer}.ah-lang-switch .active{background:linear-gradient(135deg,#70e7ff,#6e8cff 48%,#f35fe4);color:#061028}.ah-explore{display:inline-flex;align-items:center;gap:11px;min-height:50px;padding:0 22px;border-radius:18px;border:1px solid rgba(117,224,255,.34);background:rgba(4,16,37,.55);font-weight:950;box-shadow:0 0 26px rgba(89,183,255,.14)}.ah-explore span:first-child{color:var(--ah-cyan)}
.ah-main{position:relative;padding-left:var(--ah-sidebar);padding-top:var(--ah-topbar)}.ah-hero{position:relative;width:100%;min-height:760px;padding:38px 54px 54px;display:grid;grid-template-columns:minmax(430px,.74fr) minmax(500px,1.26fr);align-items:start;overflow:hidden;background-image:url('data:image/png;base64,');background-size:cover;background-position:center;background-repeat:no-repeat;border-bottom:1px solid rgba(117,224,255,.12)}.ah-hero-copy{position:relative;z-index:2;max-width:560px;padding:18px 24px 22px;margin:22px 0 0 36px;border-radius:26px;background:transparent;backdrop-filter:none}.ah-pill{display:inline-flex;align-items:center;min-height:36px;padding:0 18px;border-radius:999px;border:1px solid rgba(117,224,255,.40);background:rgba(4,18,38,.26);color:var(--ah-cyan);font-size:14px;font-weight:950;text-transform:uppercase;letter-spacing:.08em}.ah-hero h1{margin:20px 0 10px;line-height:.90;letter-spacing:-.065em;font-size:clamp(38px,4vw,68px);font-weight:950;text-shadow:0 7px 24px rgba(0,0,0,.45),0 0 20px rgba(0,0,0,.28)}.ah-hero h1 span{display:block;color:#fff}.ah-hero h1 strong{display:block;background:linear-gradient(100deg,#66dfff 5%,#6596ff 48%,#ef65df 95%);-webkit-background-clip:text;background-clip:text;color:transparent}.ah-by{margin:0 0 14px;color:rgba(255,255,255,.88);font-size:18px}.ah-by b{color:var(--ah-cyan)}.ah-status{display:inline-flex;align-items:center;gap:9px;margin:0 0 16px;min-height:38px;padding:0 15px;border-radius:10px;color:#fff;font-size:16px;font-weight:950;background:linear-gradient(90deg,rgba(89,183,255,.56),rgba(164,119,255,.42));box-shadow:0 0 20px rgba(89,183,255,.10)}.ah-status svg{width:20px;height:20px}.ah-lead{margin:0;max-width:520px;color:rgba(239,245,255,.92);font-size:16px;line-height:1.72;text-shadow:0 2px 10px rgba(0,0,0,.18)}.ah-actions{display:flex;gap:14px;flex-wrap:wrap;margin-top:24px}.ah-btn{display:inline-flex;align-items:center;justify-content:center;min-height:46px;padding:11px 18px;border-radius:14px;color:#fff;font-weight:950;border:1px solid rgba(117,224,255,.28);background:rgba(4,15,35,.54)}.ah-btn-main{border-color:rgba(117,224,255,.58);background:linear-gradient(135deg,#70e7ff,#6e8cff 48%,#f35fe4);color:#061028;box-shadow:0 0 24px rgba(117,224,255,.18)}.ah-hero-art{min-height:540px;pointer-events:none}
.ah-product-row,.ah-info-strip,.ah-section,.ah-footer{width:min(1450px,calc(100vw - var(--ah-sidebar) - 64px));margin-left:auto;margin-right:auto}.ah-product-row{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:14px;margin-top:-24px;position:relative;z-index:3}.ah-mini-card{min-height:142px;border-radius:22px;border:1px solid var(--ah-border);background:linear-gradient(180deg,rgba(7,18,42,.78),rgba(5,11,28,.66));box-shadow:var(--ah-shadow);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;gap:9px;transition:.2s;position:relative;overflow:hidden;backdrop-filter:blur(8px)}.ah-mini-card::before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 50% 0%,rgba(117,224,255,.10),transparent 48%);opacity:.82}.ah-mini-card>*{position:relative}.ah-mini-card:hover{transform:translateY(-5px);border-color:rgba(117,224,255,.45);box-shadow:0 24px 72px rgba(0,0,0,.35),0 0 24px rgba(117,224,255,.11)}.ah-mini-icon{width:42px;height:42px;display:grid;place-items:center;filter:drop-shadow(0 0 14px rgba(117,224,255,.30))}.ah-mini-icon svg{width:37px;height:37px;stroke-width:1.75}.blue{color:#3caeff}.violet{color:#a06aff}.green{color:#6df08b}.cyan{color:#66f3ff}.pink{color:#e56aff}.ah-mini-card h2{margin:0;font-size:16px}.ah-tag{display:inline-flex;align-items:center;justify-content:center;font-size:12px;line-height:1;padding:7px 11px;border-radius:999px;font-style:normal;font-weight:950}.ah-green{color:#9cffbe;background:rgba(55,220,114,.15);border:1px solid rgba(91,255,151,.30)}.ah-amber{color:#ffd789;background:rgba(255,190,55,.13);border:1px solid rgba(255,202,83,.28)}.ah-blue{color:#92dfff;background:rgba(74,168,255,.13);border:1px solid rgba(120,210,255,.26)}
.ah-info-strip{margin-top:34px;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border:1px solid var(--ah-border);border-radius:26px;overflow:hidden;background:linear-gradient(90deg,rgba(7,18,42,.62),rgba(24,18,56,.42),rgba(7,18,42,.62));box-shadow:var(--ah-shadow);backdrop-filter:blur(8px)}.ah-info-strip article{display:flex;align-items:center;gap:20px;padding:28px 34px;border-right:1px solid rgba(117,224,255,.13)}.ah-info-strip article:last-child{border-right:0}.ah-info-strip span{width:58px;height:58px;flex:0 0 58px;border-radius:50%;display:grid;place-items:center;background:rgba(74,168,255,.13);border:1px solid rgba(117,224,255,.30);box-shadow:0 0 20px rgba(74,168,255,.16);color:#9eeeff;font-size:24px}.ah-info-strip h2{margin:0 0 6px;color:var(--ah-cyan);font-size:18px}.ah-info-strip p{margin:0;color:var(--ah-muted);line-height:1.55}.ah-section{padding:84px 0 0}.ah-section-head p{margin:0 0 10px;color:var(--ah-cyan);text-transform:uppercase;letter-spacing:.09em;font-size:13px;font-weight:950}.ah-section-head h2{margin:0;font-size:clamp(36px,4.4vw,64px);line-height:1.03;letter-spacing:-.055em}.ah-section-head span{display:block;margin-top:14px;max-width:880px;color:var(--ah-muted);line-height:1.7}.ah-project-grid{margin-top:28px;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.ah-project-card{min-height:230px;border-radius:24px;border:1px solid var(--ah-border);background:linear-gradient(180deg,rgba(9,20,48,.72),rgba(5,11,28,.66));padding:26px;box-shadow:var(--ah-shadow);backdrop-filter:blur(8px)}.ah-project-card b{display:block;font-size:22px;margin-bottom:10px}.ah-project-card em{display:inline-flex;color:#ffd789;font-style:normal;font-size:12px;font-weight:950;text-transform:uppercase;letter-spacing:.06em}.ah-project-card p{color:var(--ah-muted);line-height:1.6}.ah-project-card a{color:var(--ah-cyan);font-weight:900}.ah-contact-box{margin-top:28px;display:flex;flex-wrap:wrap;gap:14px;padding:22px;border-radius:22px;border:1px solid var(--ah-border);background:rgba(5,12,28,.54);backdrop-filter:blur(6px)}.ah-contact-box a{padding:13px 17px;border-radius:14px;border:1px solid rgba(117,224,255,.26);background:rgba(4,15,35,.56);font-weight:900}.ah-footer{position:relative;z-index:1;padding:34px 0 44px;color:rgba(224,236,255,.76);display:flex;justify-content:space-between;gap:30px;border-top:1px solid rgba(117,224,255,.12);margin-top:74px}.ah-footer nav{display:flex;gap:18px;flex-wrap:wrap;justify-content:flex-end}.ah-footer a:hover{color:var(--ah-cyan)}
.ah-drawer-backdrop{position:fixed;inset:0;z-index:80;background:rgba(0,0,0,.38);backdrop-filter:blur(3px)}.ah-login-drawer{position:fixed;top:calc(var(--ah-topbar) + 18px);left:calc(var(--ah-sidebar) + 18px);z-index:90;width:min(430px,calc(100vw - var(--ah-sidebar) - 36px));padding:30px;border-radius:26px;border:1px solid rgba(117,224,255,.36);background:linear-gradient(150deg,rgba(4,13,32,.96),rgba(21,15,50,.93));box-shadow:0 30px 100px rgba(0,0,0,.42),0 0 34px rgba(117,224,255,.12);transform:translateX(-36px) scale(.96);opacity:0;pointer-events:none;transition:.22s ease}.ah-login-drawer.is-open{transform:translateX(0) scale(1);opacity:1;pointer-events:auto}.ah-drawer-close{position:absolute;right:16px;top:14px;width:38px;height:38px;border-radius:12px;border:1px solid rgba(117,224,255,.24);background:rgba(255,255,255,.05);color:#fff;font-size:26px;line-height:1;cursor:pointer}.ah-drawer-kicker{margin:0 0 10px;color:var(--ah-cyan);text-transform:uppercase;letter-spacing:.09em;font-size:13px;font-weight:950}.ah-login-drawer h2{margin:0 0 10px;font-size:42px;letter-spacing:-.055em;line-height:1}.ah-drawer-text,.ah-drawer-note{color:var(--ah-muted);line-height:1.6}.ah-drawer-form{display:grid;gap:14px;margin-top:20px}.ah-drawer-form label{display:grid;gap:8px;color:rgba(255,255,255,.85);font-weight:850}.ah-drawer-form input{width:100%;min-height:48px;color:var(--ah-text);background:rgba(2,8,22,.72);border:1px solid rgba(117,224,255,.28);border-radius:14px;padding:12px 14px;outline:none}.ah-drawer-form input:focus{border-color:rgba(117,224,255,.64);box-shadow:0 0 0 4px rgba(117,224,255,.08)}.ah-drawer-form button{min-height:48px;border:0;border-radius:14px;padding:12px 18px;font-weight:950;color:#061028;cursor:pointer;background:linear-gradient(135deg,#70e7ff,#6e8cff 48%,#f35fe4);box-shadow:0 0 24px rgba(117,224,255,.16)}.ah-login-error{margin:0;color:#ff8a8a;font-weight:900}
@media (max-width:1280px){.ah-hero{grid-template-columns:1fr;min-height:840px;background-position:64% center}.ah-hero-copy{max-width:700px}.ah-hero-art{min-height:280px}.ah-product-row{grid-template-columns:repeat(2,minmax(0,1fr));margin-top:18px}.ah-project-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media (max-width:920px){:root{--ah-sidebar:0px;--ah-topbar:auto}.ah-sidebar{display:none}.ah-topbar{position:sticky;left:0;padding:14px 16px;flex-wrap:wrap;height:auto}.ah-top-nav{overflow-x:auto;gap:22px;width:100%;padding-left:0}.ah-top-nav a{padding:10px 0 12px;white-space:nowrap}.ah-topbar-right{width:100%;justify-content:space-between}.ah-main{padding-left:0;padding-top:0}.ah-hero{width:100%;min-height:800px;padding:22px 18px 24px;grid-template-columns:1fr;background-position:67% center}.ah-hero-copy{margin:0;padding:18px}.ah-hero h1{font-size:clamp(44px,13vw,72px)}.ah-product-row,.ah-info-strip,.ah-section,.ah-footer{width:calc(100vw - 34px)}.ah-product-row{grid-template-columns:1fr}.ah-info-strip{grid-template-columns:1fr}.ah-info-strip article{border-right:0;border-bottom:1px solid rgba(117,224,255,.13)}.ah-project-grid{grid-template-columns:1fr}.ah-footer{flex-direction:column}.ah-footer nav{justify-content:flex-start}.ah-login-drawer{top:18px;left:18px;width:calc(100vw - 36px)}}
